const category = body.category || "general";

const mensajeDemasiadoCorto = message.length < 5;
const sanitizedMessage = mensajeDemasiadoCorto
  ? `El usuario envió un mensaje muy corto: "${message}". Pídele amablemente que amplíe su consulta.`
  : message;

return [{ json: {
  sessionId,
  category,
  sanitizedMessage,
  _debug_message: message
}}];

